define('taoQtiItem/qtiCreator/component/itemAuthoring',['lodash', 'ui/component', 'core/pluginLoader', 'taoQtiItem/qtiCreator/itemCreator', 'taoQtiItem/qtiCreator/editor/areaBroker', 'tpl!taoQtiItem/qtiCreator/component/tpl/itemAuthoring', 'tpl!taoQtiItem/qtiCreator/tpl/layout/interactionsPanel', 'tpl!taoQtiItem/qtiCreator/tpl/layout/itemPanel', 'tpl!taoQtiItem/qtiCreator/tpl/layout/propertiesPanel', 'css!taoQtiItemCss/qti-runner.css', 'css!taoQtiItemCss/themes/default.css', 'css!taoQtiItemCss/item-creator.css'], function (_, componentFactory, pluginLoaderFactory, itemCreatorFactory, areaBrokerFactory, componentTpl, interactionsPanelTpl, itemPanelTpl, propertiesPanelTpl) {
  'use strict';
  function itemAuthoringFactory(container, config) {
    var areaBroker;
    var itemCreator;
    var pluginLoader = pluginLoaderFactory();
    var api = {
      getItemCreator() {
        return itemCreator;
      },
      getAreaBroker() {
        return areaBroker;
      }
    };
    var itemAuthoring = componentFactory(api).setTemplate(componentTpl).on('init', function () {
      _.forEach(this.getConfig().plugins, plugin => {
        if (plugin && plugin.module) {
          if (plugin.exclude) {
            pluginLoader.remove(plugin.module);
          } else {
            pluginLoader.add(plugin);
          }
        }
      });
      pluginLoader.load().then(() => this.render(container)).catch(err => this.trigger('error', err));
    }).on('render', function () {
      var $container = this.getElement();
      var panels = [interactionsPanelTpl, itemPanelTpl, propertiesPanelTpl];
      var $wrapper = $('#item-editor-wrapper', $container);
      panels.forEach(panel => $wrapper.append(panel()));
      areaBroker = areaBrokerFactory($container, {
        menu: $container.find('.menu'),
        menuLeft: $container.find('.menu-left'),
        menuRight: $container.find('.menu-right'),
        contentCreatorPanel: $container.find('#item-editor-panel'),
        editorBar: $container.find('#item-editor-panel .item-editor-bar'),
        editorWrapper: $container.find('#item-editor-wrapper'),
        title: $container.find('#item-editor-panel .item-editor-bar h1'),
        toolbar: $container.find('#item-editor-panel .item-editor-bar #toolbar-top'),
        interactionPanel: $container.find('#item-editor-interaction-bar'),
        propertyPanel: $container.find('#item-editor-item-widget-bar'),
        itemPanel: $container.find('#item-editor-scroll-inner'),
        itemPropertyPanel: $container.find('#sidebar-right-item-properties'),
        itemCommentsPanel: $container.find('#item-editor-item-comments-bar'),
        itemStylePanel: $container.find('#item-style-editor-bar'),
        modalContainer: $container.find('#modal-container'),
        elementPropertyPanel: $container.find('#item-editor-body-element-property-bar .panel')
      });
      itemCreator = itemCreatorFactory(this.getConfig(), areaBroker, pluginLoader.getPlugins()).spread(this, 'error success ready').on('init', function () {
        this.render();
      }).init();
    }).on('destroy', function () {
      if (itemCreator) {
        itemCreator.destroy();
      }
      itemCreator = null;
      areaBroker = null;
    });
    _.defer(() => itemAuthoring.init(config));
    return itemAuthoring;
  }
  return itemAuthoringFactory;
});
