define('taoQtiItem/qtiCreator/widgets/static/object/states/Sleep',['taoQtiItem/qtiCreator/widgets/states/factory', 'taoQtiItem/qtiCreator/widgets/static/states/Sleep', 'taoQtiItem/qtiCreator/widgets/helpers/featureFlags'], function (stateFactory, SleepState, featureFlags) {
  'use strict';

  var ObjectStateSleep = stateFactory.create(SleepState, function () {
    var _widget = this.widget;
    var qtiObject = _widget.element;
    var $container = _widget.$original;
    var $widgetBox = _widget.$container;
    var $toolbar = $widgetBox.find('.mini-tlb[data-edit]');
    var compactAppearance = !!qtiObject.hasClass('compact-appearance');
    if (/audio/.test(qtiObject.attr('type')) && compactAppearance && featureFlags.isCompactAppearanceAvailable()) {
      $container.parent().addClass('compact-appearance');
    }
    $widgetBox.on('mouseenter.sleep', function (e) {
      e.stopPropagation();
      $widgetBox.addClass('hover');
      $toolbar.show();
    });
    $(document).on('click.sleep-' + _widget.serial, function (e) {
      if (!$widgetBox.is(e.target) && $widgetBox.has(e.target).length === 0) {
        $toolbar.hide();
        $widgetBox.removeClass('hover');
      }
    });
  }, function () {
    var _widget = this.widget;
    var $widgetBox = _widget.$container;
    var $toolbar = $widgetBox.find('.mini-tlb[data-edit]');
    $toolbar.hide();
    $widgetBox.removeClass('hover');
    $widgetBox.off('.sleep');
    $(document).off('.sleep-' + _widget.serial);
  });
  return ObjectStateSleep;
});
