define('taoQtiItem/qtiCreator/renderers/interactions/EndAttemptInteraction',['jquery', 'lodash', 'taoQtiItem/qtiCommonRenderer/renderers/interactions/EndAttemptInteraction', 'taoQtiItem/qtiCreator/widgets/interactions/endAttemptInteraction/Widget', 'tpl!taoQtiItem/qtiCreator/tpl/inlineInteraction/endAttemptInteraction.placeholder'], function ($, _, EndAttemptInteraction, EndAttemptInteractionWidget, tpl) {
  'use strict';

  var CreatorEndAttemptInteraction = _.clone(EndAttemptInteraction);
  CreatorEndAttemptInteraction.template = tpl;
  CreatorEndAttemptInteraction.render = function (interaction, options) {
    options = options || {};
    var interactionsConfig = this.getOption('interactions');
    if (interactionsConfig.endAttempt) {
      options.config = interactionsConfig.endAttempt;
    }
    EndAttemptInteractionWidget.build(interaction, $('.endAttemptInteraction-placeholder[data-serial="' + interaction.serial + '"]'), this.getOption('interactionOptionForm'), this.getOption('responseOptionForm'), options);
  };
  return CreatorEndAttemptInteraction;
});
